/**
 * Object storage abstraction (ARCHITECTURE.md §12).
 * Keys are generated by the server (random UUID-based), never by clients.
 */
export interface UploadUrlOptions {
  contentType: string;
  maxBytes: number;
  expiresInSeconds?: number;
}

export interface DownloadUrlOptions {
  expiresInSeconds?: number;
  /** Suggested filename for Content-Disposition (sanitized by the driver). */
  filename?: string;
  disposition?: 'inline' | 'attachment';
}

export interface PresignedUpload {
  url: string;
  method: 'PUT';
  headers: Record<string, string>;
  expiresAt: string;
}

export interface ObjectInfo {
  size: number;
  contentType?: string;
}

export interface StorageService {
  readonly driver: 's3' | 'local';
  putObject(key: string, body: Buffer, contentType: string): Promise<void>;
  getObject(key: string): Promise<Buffer>;
  /** Reads at most `bytes` from the start of the object (for magic-byte sniffing). */
  getObjectHead(key: string, bytes: number): Promise<Buffer>;
  headObject(key: string): Promise<ObjectInfo | null>;
  deleteObject(key: string): Promise<void>;
  createUploadUrl(key: string, options: UploadUrlOptions): Promise<PresignedUpload>;
  createDownloadUrl(key: string, options?: DownloadUrlOptions): Promise<string>;
  /** Readiness probe. */
  check(): Promise<void>;
}

export const DEFAULT_URL_TTL_SECONDS = 300;

const KEY_PATTERN = /^[a-z0-9][a-z0-9/_.-]{0,500}$/;

/** Rejects keys that could escape the storage root or are not server-shaped. */
export function assertSafeKey(key: string): void {
  if (!KEY_PATTERN.test(key) || key.includes('..') || key.includes('//')) {
    throw new Error(`Unsafe storage key: ${key}`);
  }
}

/** Strips characters that could break a Content-Disposition header. */
export function sanitizeFilename(name: string): string {
  const cleaned = name
    .normalize('NFKC')
    .replace(/[\r\n"\\/]/g, '_')
    .replace(/[^\x20-\x7E]/g, '_')
    .trim()
    .slice(0, 150);
  return cleaned || 'download';
}
